            for tx, ty, _, _ in their_opts:
                d = dist2(nx, ny, tx, ty)
                if d < best_dist:
                    best_dist = d
            val = best_dist

        # tie-break: prefer higher mobility
        if best_val is None or val > best_val:
            best_val = val
            best = (dx, dy)
